package com.sdya.fund.config;import com.sdya.fund.service.UserDetailsServiceImpl;import lombok.RequiredArgsConstructor;import org.springframework.context.annotation.*;import org.springframework.security.authentication.dao.DaoAuthenticationProvider;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;
@Configuration @RequiredArgsConstructor public class SecurityConfig{private final UserDetailsServiceImpl uds;@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}@Bean DaoAuthenticationProvider authProvider(){var p=new DaoAuthenticationProvider();p.setUserDetailsService(uds);p.setPasswordEncoder(passwordEncoder());return p;}@Bean SecurityFilterChain filter(HttpSecurity http)throws Exception{return http.authenticationProvider(authProvider()).authorizeHttpRequests(a->a.requestMatchers("/css/**","/js/**","/img/**","/login").permitAll().requestMatchers("/users/**").hasRole("ADMIN").anyRequest().authenticated()).formLogin(f->f.loginPage("/login").defaultSuccessUrl("/dashboard",true).permitAll()).logout(l->l.logoutSuccessUrl("/login?logout")).headers(h->h.frameOptions(x->x.sameOrigin())).build();}}
